//! The M7 metrics of bench/GRADING.md: citations, dropped work, refutations without a
//! discriminator, decoys per archetype row, agreement per fixture, tokens, and the residual
//! share. The synthetic sample is testdata/m7-sample (generated by hand, numbers checked
//! by hand in the comments).

use std::{fs, path::Path};

use dla_bench::{
    grade::{self, Source, State, grade_findings, read_ledger_bytes},
    metrics_ext::{Agreement, DecoyRow, RunOutcome, ledger_extra, report_is_complete},
    model::{Expected, Group, MetricsFile},
};

fn sample() -> MetricsFile {
    let s = Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/m7-sample");
    grade::grade_dir(&s.join("results"), &s.join("fixtures")).expect("grades")
}

fn gates_on(m: &MetricsFile) -> &Group {
    m.groups
        .iter()
        .find(|g| g.ablation == "gates" && g.archetypes == "on")
        .expect("gates/on group")
}

fn counts(r: &Option<dla_bench::model::Ratio>) -> (u64, u64, Vec<(u64, u64)>) {
    let r = r.as_ref().expect("metric is present");
    (
        r.num,
        r.den,
        r.per_run.iter().map(|p| (p.num, p.den)).collect(),
    )
}

#[test]
fn uncited_findings_count_supports_contradicts_and_transition_evidence() {
    // Run 2 of m7-leak: F2 has no evidence id at all (1 of 25 findings, none of the
    // hypotheses counts). F1 is added without supports but its transition cites E3.
    let m = sample();
    let g = gates_on(&m);
    assert_eq!(
        counts(&g.metrics.uncited_findings),
        (1, 25, vec![(0, 8), (1, 8), (0, 9)])
    );
}

#[test]
fn uncited_checklist_answers_use_the_latest_answer_and_skip_unresolved() {
    // Run 1: scope answered with E1; target is unresolved (left out) -> 0/1.
    // Run 2: build answered twice, the later with E4; scope is partial with no evidence -> 1/2.
    let m = sample();
    let g = gates_on(&m);
    assert_eq!(
        counts(&g.metrics.uncited_checklist_answers),
        (1, 3, vec![(0, 1), (1, 2), (0, 0)])
    );
}

#[test]
fn dropped_rate_counts_only_runs_with_a_complete_report() {
    // Run 2: m7-leak holds a candidate (F2) under a COMPLETE report, and m7-multi has a
    // residual row over its threshold whose open item O2 is not resolved -> 2 of 7.
    // Run 3: the m7-leak report is INCOMPLETE and left out (6 runs); m7-multi's open item
    // jvm/O1 is resolved and the row names it as O1 -> not dropped.
    let m = sample();
    let g = gates_on(&m);
    assert_eq!(
        counts(&g.metrics.dropped_rate),
        (2, 20, vec![(0, 7), (2, 7), (0, 6)])
    );
}

#[test]
fn no_skill_runs_have_no_ledger_counts_and_undiscriminated_refutations_count() {
    let m = sample();
    let g = m
        .groups
        .iter()
        .find(|g| g.ablation == "no-skill")
        .expect("no-skill group");
    // One refutation has a discriminator, the other a blank one.
    assert_eq!(
        counts(&g.metrics.undiscriminated_refutations),
        (1, 2, vec![(1, 2)])
    );
    assert_eq!(counts(&g.metrics.uncited_findings).1, 0);
    assert_eq!(counts(&g.metrics.dropped_rate).1, 0);
    // A ledger refutation always has a discriminator.
    let gates = gates_on(&m);
    assert_eq!(counts(&gates.metrics.undiscriminated_refutations).0, 0);
    assert!(counts(&gates.metrics.undiscriminated_refutations).1 > 0);
}

#[test]
fn decoy_rows_pass_only_when_the_leak_is_found_every_run_and_the_decoy_never_claims() {
    let m = sample();
    let g = gates_on(&m);
    let a = &g.decoys["L-COLLECT"];
    assert_eq!(a.pairs, ["m7-leak/m7-decoy"]);
    assert_eq!((a.leak.found_runs, a.leak.runs), (3, 3));
    assert_eq!((a.decoy.claim_runs, a.decoy.runs), (0, 3));
    assert!(a.pass);
    // L-REGISTER: the leak is missed in run 2 and the decoy claims in run 3.
    let b = &g.decoys["L-REGISTER"];
    assert_eq!((b.leak.found_runs, b.leak.runs), (2, 3));
    assert_eq!((b.decoy.claim_runs, b.decoy.runs), (1, 3));
    assert!(!b.pass);
    // A group that never ran the decoy has no data and does not pass.
    let ns = m.groups.iter().find(|g| g.ablation == "no-skill").unwrap();
    assert!(!ns.decoys["L-COLLECT"].pass);
}

#[test]
fn a_decoy_row_needs_runs_on_both_sides() {
    let mut row = DecoyRow::default();
    row.settle();
    assert!(!row.pass);
    row.leak.runs = 2;
    row.leak.found_runs = 2;
    row.settle();
    assert!(!row.pass, "no decoy run");
    row.decoy.runs = 2;
    row.settle();
    assert!(row.pass);
    row.decoy.claim_runs = 1;
    row.settle();
    assert!(!row.pass);
}

#[test]
fn agreement_lists_the_outcome_of_every_run() {
    let m = sample();
    let g = gates_on(&m);
    let multi = &g.fixtures["m7-multi"].agreement;
    assert_eq!(multi.runs, 3);
    assert!(!multi.unanimous);
    let outcomes: Vec<&str> = multi.outcomes.iter().map(|o| o.outcome.as_str()).collect();
    assert_eq!(outcomes, ["found:L1,L2", "found:L1", "found:L1,L2"]);
    assert!(g.fixtures["m7-leak"].agreement.unanimous);
    let decoy2: Vec<&str> = g.fixtures["m7-decoy2"]
        .agreement
        .outcomes
        .iter()
        .map(|o| o.outcome.as_str())
        .collect();
    assert_eq!(decoy2, ["no-claim", "no-claim", "claim"]);
    let one = Agreement::of(vec![RunOutcome {
        run: 1,
        outcome: "claim".into(),
    }]);
    assert!(one.unanimous);
    assert!(Agreement::of(Vec::new()).unanimous);
}

#[test]
fn fixture_tokens_are_the_sum_of_the_four_usage_fields_over_the_runs() {
    // m7-leak: 3 runs of (10 + 20 + 300 + 40) = 370 tokens each.
    let m = sample();
    assert_eq!(gates_on(&m).fixtures["m7-leak"].tokens_total, 1110);
    // m7-decoy: 3 runs of 1 + 2 + 3 + 4.
    assert_eq!(gates_on(&m).fixtures["m7-decoy"].tokens_total, 30);
}

#[test]
fn a_shrinking_region_does_not_lower_the_unexplained_total() {
    // Rows of the sample: residual 4 of total 10 (heap) and residual 0 of total -5
    // (non-heap) in one run. The negative total counts as 0, so the share stays <= 1.
    let m = sample();
    let share = gates_on(&m)
        .unexplained_growth_share
        .value
        .expect("a share");
    assert!((0.0..=1.0).contains(&share), "{share}");
    let t = tempfile::tempdir().unwrap();
    let (fx, res) = (
        t.path().join("fx"),
        t.path().join("res/runs/gates/archetypes-on/f/1"),
    );
    fs::create_dir_all(fx.join("f")).unwrap();
    fs::create_dir_all(&res).unwrap();
    fs::write(
        fx.join("f/expected.toml"),
        "schema_version = 1\nid = \"f\"\nruntime = \"python\"\ncategory = \"impossible\"\ndynamic_confirmation = false\n[task]\nprompt = \"p\"\n",
    )
    .unwrap();
    fs::write(
        res.join("run.json"),
        r#"{"exit_code":0,"timed_out":false,"usage":{}}"#,
    )
    .unwrap();
    fs::write(
        res.join("coverage.json"),
        r#"{"residual":[{"residual":1448.0,"total_slope":1448.0},{"residual":0.0,"total_slope":-5.873}]}"#,
    )
    .unwrap();
    let m = grade::grade_dir(&t.path().join("res"), &fx).unwrap();
    assert_eq!(m.groups[0].unexplained_growth_share.value, Some(1.0));
}

fn read(text: &str) -> dla_bench::grade::LedgerRead {
    read_ledger_bytes(text.as_bytes()).expect("a finding")
}

#[test]
fn the_report_status_line_decides_complete() {
    assert!(report_is_complete("# DLA report\n\nStatus: COMPLETE\n"));
    assert!(report_is_complete("Status: COMPLETE\r\n"));
    assert!(!report_is_complete("Status: INCOMPLETE (1 open)\n"));
    assert!(!report_is_complete("no status line\n"));
    // The first status line decides, not a later mention in a finding.
    assert!(!report_is_complete(
        "Status: INCOMPLETE (1 open)\nStatus: COMPLETE\n"
    ));
    assert!(!report_is_complete("Status: COMPLETE.\n"));
}

#[test]
fn a_merged_duplicate_hands_its_evidence_to_the_canonical_finding() {
    let text = concat!(
        r#"{"type":"finding_added","worker":"a","finding":{"id":"F1","site":"x:1"}}"#,
        "\n",
        r#"{"type":"finding_added","worker":"b","finding":{"id":"F1","site":"x:1","supports":["E7"]}}"#,
        "\n",
        r#"{"type":"finding_merged","canonical":"a/F1","duplicate":"b/F1"}"#,
        "\n",
    );
    let x = ledger_extra(&read(text), text.as_bytes(), None, None);
    assert_eq!(x.uncited_findings, (0, 1));
    let alone = r#"{"type":"finding_added","worker":"a","finding":{"id":"F1","site":"x:1"}}"#;
    let x = ledger_extra(&read(alone), alone.as_bytes(), None, None);
    assert_eq!(x.uncited_findings, (1, 1));
    // A merged-away finding is not counted at all.
    let text = concat!(
        r#"{"type":"finding_added","worker":"a","finding":{"id":"F1","site":"x:1","supports":["E1"]}}"#,
        "\n",
        r#"{"type":"finding_added","worker":"b","finding":{"id":"F1","site":"x:1"}}"#,
        "\n",
        r#"{"type":"finding_merged","canonical":"a/F1","duplicate":"b/F1"}"#,
        "\n",
    );
    assert_eq!(
        ledger_extra(&read(text), text.as_bytes(), None, None).uncited_findings,
        (0, 1)
    );
}

#[test]
fn empty_and_non_string_evidence_ids_do_not_cite() {
    let text =
        r#"{"type":"finding_added","finding":{"id":"F1","supports":["",7,null],"contradicts":[]}}"#;
    let x = ledger_extra(&read(text), text.as_bytes(), None, None);
    assert_eq!(x.uncited_findings, (1, 1));
}

#[test]
fn a_residual_row_over_its_threshold_is_dropped_unless_its_open_item_is_resolved() {
    let ledger = concat!(
        r#"{"type":"finding_added","finding":{"id":"F1","supports":["E1"]}}"#,
        "\n",
        r#"{"type":"transition","finding":"F1","to":"confirmed"}"#,
        "\n",
        r#"{"type":"open_item","id":"O1","text":"unexplained growth: 9 bytes/n in heap (S1); x"}"#,
        "\n",
    );
    let r = read(ledger);
    let complete = Some("Status: COMPLETE\n");
    let row = |item: &str, residual: f64| {
        format!(
            r#"{{"residual":[{{"region":"heap","residual":{residual},"threshold":5.0,"open_item":{item}}}]}}"#
        )
    };
    let dropped = |cov: &str, ledger: &str| {
        let r = read(ledger);
        ledger_extra(&r, ledger.as_bytes(), complete, Some(cov)).dropped
    };
    // Under the threshold: fine whatever the item.
    assert_eq!(dropped(&row("null", 5.0), ledger), (0, 1));
    // Over the threshold with no open item.
    assert_eq!(dropped(&row("null", 5.5), ledger), (1, 1));
    // Over, the item exists but is not resolved.
    assert_eq!(dropped(&row("\"O1\"", 5.5), ledger), (1, 1));
    // Resolved.
    let resolved = format!(
        "{ledger}{}\n",
        r#"{"type":"open_item_resolved","id":"O1","resolution":{"hypothesis":"F1"}}"#
    );
    assert_eq!(dropped(&row("\"O1\"", 5.5), &resolved), (0, 1));
    // The row names an item that does not exist.
    assert_eq!(dropped(&row("\"O9\"", 5.5), &resolved), (1, 1));
    // An incomplete report is not measured.
    let x = ledger_extra(
        &r,
        ledger.as_bytes(),
        Some("Status: INCOMPLETE (1 open)\n"),
        None,
    );
    assert_eq!(x.dropped, (0, 0));
    // A missing report is not measured either.
    assert_eq!(
        ledger_extra(&r, ledger.as_bytes(), None, None).dropped,
        (0, 0)
    );
}

#[test]
fn a_residual_item_resolved_under_a_worker_prefix_covers_the_plain_id_of_the_same_region() {
    let ledger = concat!(
        r#"{"type":"finding_added","finding":{"id":"F1","supports":["E1"]}}"#,
        "\n",
        r#"{"type":"transition","finding":"F1","to":"confirmed"}"#,
        "\n",
        r#"{"type":"open_item","id":"jvm/O1","text":"unexplained growth: 9 bytes/n in heap (S1); x"}"#,
        "\n",
        r#"{"type":"open_item_resolved","id":"jvm/O1"}"#,
        "\n",
    );
    let r = read(ledger);
    let cov = |region: &str| {
        format!(
            r#"{{"residual":[{{"region":"{region}","residual":9.0,"threshold":1.0,"open_item":"O1"}}]}}"#
        )
    };
    let dropped = |region: &str| {
        ledger_extra(
            &r,
            ledger.as_bytes(),
            Some("Status: COMPLETE\n"),
            Some(&cov(region)),
        )
        .dropped
    };
    assert_eq!(dropped("heap"), (0, 1));
    assert_eq!(
        dropped("non-heap"),
        (1, 1),
        "an item about another region does not cover it"
    );
}

fn exp(category: &str) -> Expected {
    toml::from_str(&format!(
        "schema_version = 1\nid = \"t\"\nruntime = \"python\"\ncategory = \"{category}\"\ndynamic_confirmation = true\n[task]\nprompt = \"p\"\n"
    ))
    .unwrap()
}

#[test]
fn refutations_without_a_discriminator_are_counted_in_grade_findings() {
    let f = |state, disc| grade::Finding {
        state,
        site: None,
        owner: None,
        worker: None,
        holder: None,
        label: None,
        hypothesis: false,
        discriminator: disc,
    };
    let g = grade_findings(
        &exp("non-leak"),
        Source::Findings,
        &[
            f(State::Refuted, true),
            f(State::Refuted, false),
            f(State::Confirmed, false),
        ],
    );
    assert_eq!(g.parts[13], (1, 2));
    assert_eq!(g.outcome, "claim");
}

#[test]
fn the_table_renders_the_m7_metric_rows_and_the_decoys_table() {
    use dla_bench::table;
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/m7-sample/expected-metrics.json");
    let m: MetricsFile = serde_json::from_str(&fs::read_to_string(p).unwrap()).unwrap();
    let md = table::render(&m);
    for row in [
        "| uncited_findings | 0.0400 | 1/25 | 0.0417 ± 0.0589 |",
        "| uncited_checklist_answers | 0.3333 | 1/3 | 0.2500 ± 0.2500 |",
        "| dropped_rate | 0.1000 | 2/20 | 0.0952 ± 0.1347 |",
        "| undiscriminated_refutations | 0.0000 | 0/9 | 0.0000 ± 0.0000 |",
    ] {
        assert!(md.contains(row), "missing {row}:\n{md}");
    }
    // The decoys table lists a passing and a failing row of the gates arm.
    assert!(md.contains("### Decoys"), "{md}");
    assert!(
        md.contains("| L-COLLECT | m7-leak/m7-decoy | 3/3 | 0/3 | yes |"),
        "{md}"
    );
    assert!(
        md.contains("| L-REGISTER | m7-pair2/m7-decoy2 | 2/3 | 1/3 | no |"),
        "{md}"
    );
    // The no-skill arm has a decoys row with no decoy runs: it fails and says so.
    assert!(
        md.contains("| L-COLLECT | m7-leak/m7-decoy | 1/1 | 0/0 | no |"),
        "{md}"
    );
    // A group without decoys has no Decoys heading.
    let mut g = m.groups[0].clone();
    g.decoys.clear();
    assert!(!table::render_group(&g).contains("### Decoys"));
}
